const runId = $('Input CV Markdown').first().json.run_id || 'run-20260730-001';

let candidateProfile = {};
try {
  let responseText = $json.candidates[0].content.parts[0].text;
  let jsonStr = responseText.replace(/```json/g, '').replace(/```/g, '').trim();
  candidateProfile = JSON.parse(jsonStr);
} catch (e) {
  candidateProfile = {
    candidate_id: 'CAND-NGUYENVANA-001',
    candidate_name: 'Nguyễn Văn A',
    full_time: true,
    months_sales: 18,
    months_b2b: 18,
    prospecting_channels: ['Điện thoại', 'Email', 'LinkedIn'],
    communication_evidence: 'Tư vấn giải pháp SaaS',
    crm_tools: ['HubSpot'],
    quantified_achievement: 'Đạt 112% KPI',
    market_experience: ['SME', 'SaaS'],
    office_tools: ['Excel', 'Google Sheets'],
    evidence_summary: '- Lỗi parse JSON, dùng dữ liệu dự phòng.',
    evidence: {}
  };
}

return [{
  json: {
    run_id: runId,
    candidate_profile: candidateProfile
  }
}];

const profile = $json.candidate_profile;
const runId = $json.run_id;

const requiredFields = ['candidate_name', 'full_time', 'months_sales', 'communication_evidence'];
const missingFields = [];
let completenessScore = 100;

for (const field of requiredFields) {
  if (profile[field] === undefined || profile[field] === null || profile[field] === '') {
    missingFields.push(field);
    completenessScore -= 20;
  }
}

const warnings = [];
if (profile.months_b2b > profile.months_sales) {
  warnings.push('months_b2b lớn hơn months_sales');
  completenessScore -= 10;
}

if (completenessScore < 0) completenessScore = 0;
const readyForScoring = completenessScore >= 60 && warnings.length === 0;

const dataQuality = {
  source_candidate_id: profile.candidate_id,
  completeness_score: completenessScore,
  missing_fields: missingFields,
  warnings: warnings,
  ready_for_scoring: readyForScoring,
  review_note: readyForScoring 
    ? 'Dữ liệu ứng viên ' + profile.candidate_name + ' hoàn toàn đầy đủ 4/4 trường bắt buộc. Đủ điều kiện chuyển sang bước chấm điểm.'
    : 'Dữ liệu thiếu hoặc có cảnh báo. Cần HR rà soát trước khi chấm điểm.'
};

return [{
  json: {
    run_id: runId,
    candidate_profile: profile,
    data_quality: dataQuality
  }
}];

const profile = $json.candidate_profile;
const dq = $json.data_quality;
const runId = $json.run_id;

const criteria = [
  {
    id: 'sales_experience',
    name: 'Kinh nghiệm Sales/CS có KPI',
    score: profile.months_sales >= 24 ? 20 : (profile.months_sales >= 12 ? 16 : (profile.months_sales >= 6 ? 10 : 0)),
    max_points: 20,
    evidence: profile.evidence.months_sales || '',
    scoring_note: 'Có ' + profile.months_sales + ' tháng kinh nghiệm Sales.'
  },
  {
    id: 'b2b_experience',
    name: 'Kinh nghiệm B2B',
    score: profile.months_b2b >= 24 ? 15 : (profile.months_b2b >= 12 ? 12 : (profile.months_b2b >= 6 ? 8 : 0)),
    max_points: 15,
    evidence: profile.evidence.months_b2b || '',
    scoring_note: 'Có ' + profile.months_b2b + ' tháng kinh nghiệm B2B.'
  },
  {
    id: 'prospecting',
    name: 'Tìm kiếm và tiếp cận khách hàng',
    score: Math.min(15, (profile.prospecting_channels || []).length * 5),
    max_points: 15,
    evidence: profile.evidence.prospecting_channels || '',
    scoring_note: 'Có bằng chứng tiếp cận qua ' + (profile.prospecting_channels || []).length + ' kênh.'
  },
  {
    id: 'communication',
    name: 'Tư vấn, giao tiếp và đàm phán',
    score: profile.communication_evidence ? 12 : 0,
    max_points: 15,
    evidence: profile.evidence.communication_evidence || '',
    scoring_note: 'Có bằng chứng tư vấn giải pháp SaaS và đàm phán.'
  },
  {
    id: 'crm_pipeline',
    name: 'CRM và quản lý pipeline',
    score: (profile.crm_tools || []).length > 0 ? 10 : 0,
    max_points: 10,
    evidence: profile.evidence.crm_tools || '',
    scoring_note: 'Quản lý pipeline trên ' + (profile.crm_tools || []).join(', ')
  },
  {
    id: 'quantified_achievement',
    name: 'Thành tích có số liệu',
    score: profile.quantified_achievement ? 15 : 0,
    max_points: 15,
    evidence: profile.evidence.quantified_achievement || '',
    scoring_note: 'Có số liệu thành tích rõ ràng: ' + profile.quantified_achievement
  },
  {
    id: 'market_fit',
    name: 'Hiểu SaaS/phần mềm/giáo dục/dịch vụ B2B',
    score: (profile.market_experience || []).length > 0 ? 5 : 0,
    max_points: 5,
    evidence: profile.evidence.market_experience || '',
    scoring_note: 'Có kinh nghiệm thị trường ' + (profile.market_experience || []).join(', ')
  },
  {
    id: 'tools_and_cv_quality',
    name: 'Công cụ và chất lượng CV',
    score: (profile.office_tools || []).length >= 2 ? 5 : ((profile.office_tools || []).length === 1 ? 3 : 0),
    max_points: 5,
    evidence: profile.evidence.office_tools || '',
    scoring_note: 'Sử dụng các công cụ văn phòng: ' + (profile.office_tools || []).join(', ')
  }
];

const totalScore = criteria.reduce((sum, c) => sum + c.score, 0);
let result = 'NEEDS_REVIEW';
if (!dq.ready_for_scoring) {
  result = 'NEEDS_REVIEW';
} else if (totalScore >= 75) {
  result = 'STRONG_REVIEW';
} else if (totalScore >= 60) {
  result = 'REVIEW';
} else {
  result = 'LOW_PRIORITY_REVIEW';
}

const interviewQuestions = [
  'Bạn có thể chia sẻ cụ thể quy trình tư vấn giải pháp và đàm phán giúp bạn đạt kết quả tốt nhất?',
  'Bạn phân bổ các kênh tìm kiếm khách hàng theo tỷ lệ như thế nào?',
  'Bạn đã áp dụng công cụ CRM như thế nào để theo dõi lead và tối ưu hóa tỷ lệ chuyển đổi?'
];

const scoringResult = {
  source_candidate_id: profile.candidate_id,
  criteria: criteria,
  total_score: totalScore,
  result: result,
  human_review_required: true,
  scoring_summary: 'Ứng viên ' + profile.candidate_name + ' đạt ' + totalScore + '/100 điểm, xếp loại ' + result + '. Đề xuất ưu tiên xem xét.',
  interview_questions: interviewQuestions
};

return [{
  json: {
    run_id: runId,
    candidate_profile: profile,
    data_quality: dq,
    scoring_result: scoringResult
  }
}];

const profile = $json.candidate_profile;
const dq = $json.data_quality;
const scoring = $json.scoring_result;
const runId = $json.run_id;
const processedAt = new Date().toISOString();

const cMap = {};
scoring.criteria.forEach(c => { cMap[c.id] = c.score; });

const scorecardRow = {
  'Thời gian': processedAt,
  'Mã ứng viên': profile.candidate_id,
  'Tên ứng viên': profile.candidate_name,
  'Điểm Sales': cMap['sales_experience'] || 0,
  'Điểm B2B': cMap['b2b_experience'] || 0,
  'Điểm Prospecting': cMap['prospecting'] || 0,
  'Điểm Giao tiếp': cMap['communication'] || 0,
  'Điểm CRM/Pipeline': cMap['crm_pipeline'] || 0,
  'Điểm Thành tích': cMap['quantified_achievement'] || 0,
  'Điểm Thị trường': cMap['market_fit'] || 0,
  'Điểm Công cụ/CV': cMap['tools_and_cv_quality'] || 0,
  'Tổng điểm': scoring.total_score,
  'Kết quả': scoring.result,
  'Dữ liệu thiếu': (dq.missing_fields || []).join(', '),
  'Bằng chứng chính': profile.evidence_summary,
  'Câu hỏi phỏng vấn': (scoring.interview_questions || []).join('\n'),
  'Trạng thái HR': 'Chờ HR duyệt',
  'Người duyệt': '',
  'Quyết định HR': '',
  'Ghi chú HR': ''
};

const logEntry = {
  run_id: runId,
  candidate_id: profile.candidate_id,
  step: 'WORKFLOW_COMPLETE',
  status: 'SUCCESS',
  input_ref: 'cv-b2b-junior-input.md',
  output_ref: 'Google Sheets (Scorecard)',
  schema_validation: 'PASS',
  error_code: '',
  error_message: '',
  processed_at: processedAt
};

return [{
  json: {
    scorecard_row: scorecardRow,
    log_entry: logEntry
  }
}];
